package main

import (
	"fmt"
	"reflect"
)

// erroneousSplice checks if input are integers, and splices accordingly
func erroneousSplice(numbers []int, delimiter int) []int {
	result := []int{}

	// Validate inputs
	if !isInt(delimiter) {
		fmt.Println("Error: Delimeter is not an integer.")
		return []int{}
	}

	for _, num := range numbers {
		if !isInt(num) {
			fmt.Println("Error: Numbers list contains non-integer element(s).")
			return []int{}
		}
	}

	for _, i := range numbers {
		for _, j := range numbers {
			result = append(result, i)
			result = append(result, delimiter)
		}
	}

	// Remove last element if list is not empty
	if len(result) > 0 {
		result = result[:len(result)-1]
	}

	return result
}

// isInt checks if the input is of type int
func isInt(value interface{}) bool {
	_, ok := value.(int)
	return ok
}

// wrapperFunc takes a list of integers and a tuple of two integers
func wrapperFunc(listOfInts []int, tupleOfInts [2]int) [][]int {
	results := [][]int{}

	for _, num := range listOfInts {
		results = append(results, erroneousSplice([]int{num}, tupleOfInts[0]))
		results = append(results, erroneousSplice([]int{num}, tupleOfInts[1]))
	}

	return results
}

func main() {
	// Example use
	result := wrapperFunc([]int{2, 3, 4}, [2]int{10, 20})
	fmt.Println(result)
}
```

