#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Function to compute GCD of two integers
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to compute GCD of an array of integers
int array_gcd(int arr[], int size) {
    if (size == 0) return 0;
    if (size == 1) return arr[0];

    int current_gcd = arr[0];
    for (int i = 1; i < size; i++) {
        current_gcd = gcd(current_gcd, arr[i]);
        if (current_gcd == 1) break; // GCD cannot be less than 1
    }
    return current_gcd;
}

// Main function to test
int main() {
    int arr1[] = {24, 36, 48};
    int arr2[] = {55, 25, 10};
    int arr3[] = {100, 150, 200};
    int arr4[] = {21, 28, 35};
    int arr5[] = {81, 54, 36};

    printf("%d\n", array_gcd(arr1, sizeof(arr1) / sizeof(arr1[0])));
    printf("%d\n", array_gcd(arr2, sizeof(arr2) / sizeof(arr2[0])));
    printf("%d\n", array_gcd(arr3, sizeof(arr3) / sizeof(arr3[0])));
    printf("%d\n", array_gcd(arr4, sizeof(arr4) / sizeof(arr4[0])));
    printf("%d\n", array_gcd(arr5, sizeof(arr5) / sizeof(arr5[0])));

    return 0;
}
```

