#include <iostream>
#include <string>
#include <cctype> // for tolower()

using namespace std;

// Function to count vowels and consonants in a given string
void countVowelsAndConsonants(const string& input) {
    int vowelCount = 0;
    int consonantCount = 0;
    int totalCharCount = 0;

    for (char ch : input) {
        if (isalpha(ch)) {
            totalCharCount++;
            char lowercaseCh = tolower(ch);
            if (lowercaseCh == 'a' || lowercaseCh == 'e' || lowercaseCh == 'i' ||
                lowercaseCh == 'o' || lowercaseCh == 'u') {
                vowelCount++;
            } else {
                consonantCount++;
            }
        }
    }

    // Determine message based on input
    if (input.empty()) {
        cout << "The string is empty.\n";
    } else if (vowelCount == 0 && consonantCount == 0) {
        cout << "The string has no alphabetic characters.\n";
    } else {
        cout << "Vowels: " << vowelCount << "\n";
        cout << "Consonants: " << consonantCount << "\n";
    }
}

int main() {
    // Test with "Hello World"
    cout << "Hello World:\n";
    countVowelsAndConsonants("Hello World");

    cout << "\nTesting other strings:\n";
    countVowelsAndConsonants("");             // Empty string
